<?php require_once __DIR__ . '/../json_db.php';session_start();if(isset($_SESSION['loggedin'])&&$_SESSION['loggedin']===true){$successMessage='';$errorMessage='';if($_SERVER['REQUEST_METHOD']==='POST'){$customerID=$_POST['customer_id'];$customerName=$_POST['customer_name'];$customerAchievement=$_POST['customer_achievement'];$customerDietplanType=$_POST['customer_dietplan_type'];$stories=jd_read('success_stories');$updated=false;foreach($stories as $i=>$s){if(isset($s['id'])&&(int)$s['id']===(int)$customerID){$stories[$i]['name']=$customerName;$stories[$i]['achievement']=$customerAchievement;$stories[$i]['dietplan_type']=$customerDietplanType;$updated=true;break;}}if($updated&&jd_write('success_stories',$stories)){$successMessage="Success story updated successfully. Redirecting to Success Stories Page . . .";echo '<script>';echo 'setTimeout(function() { window.location.href = "/success-stories.php"; }, 3000);';echo '</script>';}else{$errorMessage=$updated?"Error updating success story.":"Success story not found.";}}else{if(isset($_GET['id'])){$customerID=$_GET['id'];$stories=jd_read('success_stories');$customerName='';$customerAchievement='';$customerDietplanType='';foreach($stories as $s){if(isset($s['id'])&&(int)$s['id']===(int)$customerID){$customerName=$s['name'];$customerAchievement=$s['achievement'];$customerDietplanType=$s['dietplan_type'];break;}}}else{echo "Invalid customer ID.";exit();}}}else{header("Location: ../login.php");exit();} ?><?php include '../Header.php'; ?><div class="ttm-page-title-row"><div class="ttm-bg-layer ttm-page-title-row-bg-layer"></div><div class="container"><div class="row"><div class="text-center col-md-12"><div class="ttm-textcolor-white title-box"><div class="ttm-textcolor-white page-title-heading"><h1 class="title">Edit Success Story</h1></div><div class="breadcrumb-wrapper"><span><a href="/"title="Homepage"><i class="ti ti-home"></i> Home </a></span><span class="ttm-bread-sep">: : </span><span><span class="ttm-textcolor-skincolor">Edit Success Story</span></span></div></div></div></div></div></div><div class="clearfix edit-success-story-section ttm-row"><div class="container"><div class="row"><div class="col-md-12"><div class="text-center clearfix section-title"><div class="title-header"><h2 class="title">Edit Success Story</h2></div></div></div></div><div class="row"><div class="col-md-8 offset-md-2"><?php if(!empty($successMessage)){echo '<div class="alert alert-success" role="alert">'.$successMessage.'</div>';}if(!empty($errorMessage)){echo '<div class="alert alert-danger" role="alert">'.$errorMessage.'</div>';} ?><form action="edit_success_story"method="POST"><div class="form-group"><label for="customerName">Customer Name:</label> <input name="customer_name"value="<?php echo $customerName; ?>"class="form-control"id="customerName"required></div><div class="form-group"><label for="customerAchievement">Customer Achievement:</label> <textarea class="form-control"id="customerAchievement"name="customer_achievement"required><?php echo $customerAchievement; ?></textarea></div><div class="form-group"><label for="customerDietplanType">Customer Diet Plan Type:</label> <input name="customer_dietplan_type"value="<?php echo $customerDietplanType; ?>"class="form-control"id="customerDietplanType"required></div><input name="customer_id"value="<?php echo $customerID; ?>"type="hidden"><div class="text-center"><button class="my-4 ttm-btn ttm-btn-bgcolor-black ttm-btn-shape-round ttm-btn-size-md ttm-btn-style-fill"type="submit">Update</button></div></form></div></div><div class="text-center"><a href="/admin/add_success_story.php"class="text-center mb-20 my-4 ttm-btn ttm-btn-bgcolor-black ttm-btn-shape-round ttm-btn-size-md ttm-btn-style-fill"target="_biteandiet">Add Story</a></div></div></div><?php include '../footer.php'; ?>